param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'exception-serialization-duplicate-field-order-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('SerializationBoundarySpy'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('main');$builder=$module.DefineType('SerializationBoundarySpy',[Reflection.TypeAttributes]::Public,[Exception]);$calls=$builder.DefineField('Calls',[int],[Reflection.FieldAttributes]::Public);$others=$builder.DefineField('Others',[int],[Reflection.FieldAttributes]::Public);$returns=$builder.DefineField('ReturnValue',[string],[Reflection.FieldAttributes]::Public);$throws=$builder.DefineField('ThrowSource',[bool],[Reflection.FieldAttributes]::Public)
$ctor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@([string]));$il=$ctor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Call,[Exception].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Ret)
foreach($property in @('Source','Message','HelpLink','StackTrace','Data')){$base=[Exception].GetProperty($property).GetMethod;$method=$builder.DefineMethod($base.Name,[Reflection.MethodAttributes]'Public,Virtual,HideBySig,SpecialName',$base.ReturnType,[type[]]@());$il=$method.GetILGenerator();$field=if($property -eq 'Source'){$calls}else{$others};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$field);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$field);if($property -eq 'Source'){$label=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$throws);$il.Emit([Reflection.Emit.OpCodes]::Brtrue_S,$label);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$returns);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($label)};$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'source failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$builder.DefineMethodOverride($method,$base)};$spy=$builder.CreateType();$constructor=$spy.GetConstructor([type[]]@([string]))
function Text($units){if($null -eq $units){return $null};return [string]::new([char[]]([int[]]$units))}
function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$index=0;$nullInputControls=0
foreach($collisionName in $plan.collisions){foreach($sourceIndex in 0..2){foreach($helpIndex in 0..2){foreach($messageIndex in 0..2){foreach($mode in $plan.modes){foreach($flag in $plan.contextFlags){$arguments=[object[]]::new(1);$arguments[0]=Text $plan.texts[$messageIndex];$e=$constructor.Invoke($arguments);$setterArgs=[object[]]::new(1);$setterArgs[0]=Text $plan.texts[$sourceIndex];$null=[Exception].GetProperty('Source').SetMethod.Invoke($e,$setterArgs);$setterArgs[0]=Text $plan.texts[$helpIndex];$null=[Exception].GetProperty('HelpLink').SetMethod.Invoke($e,$setterArgs);foreach($pair in @(@('sourceIndex','_source'),@('helpIndex','_helpURL'),@('messageIndex','_message'))){$inputIndex=switch($pair[0]){'sourceIndex'{$sourceIndex};'helpIndex'{$helpIndex};'messageIndex'{$messageIndex}};if($inputIndex -eq 0){if($null -ne [Exception].GetField($pair[1],[Reflection.BindingFlags]'Instance,NonPublic').GetValue($e)){throw 'Nullable input was coerced'};$nullInputControls++}};$e.ThrowSource=$mode -eq 'throw';if($mode -eq 'text'){$e.ReturnValue='virtual source'};$context=[Runtime.Serialization.StreamingContext]::new([Runtime.Serialization.StreamingContextStates]$flag)
foreach($attempt in -1..1){$info=$null;if($attempt -ge 0){$info=[Runtime.Serialization.SerializationInfo]::new($spy,[Runtime.Serialization.FormatterConverter]::new())};if($null -ne $info){$info.AddValue($collisionName,[object]'preseed',[string])};$errorName='none';$errorMessage=$null;$errorHResult=0;try{$e.GetObjectData($info,$context)}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};if($errorValue -isnot [ArgumentNullException] -and $errorValue -isnot [InvalidOperationException] -and $errorValue -isnot [Runtime.Serialization.SerializationException]){throw};$errorName=$errorValue.GetType().FullName;$errorMessage=$errorValue.Message;$errorHResult=$errorValue.HResult};$count=0;$fields=@{};$entryNames=[Collections.Generic.List[string]]::new();if($null -ne $info){$count=$info.MemberCount;$enumerator=$info.GetEnumerator();while($enumerator.MoveNext()){$entry=$enumerator.Current;$fields[$entry.Name]=$entry.Value;$entryNames.Add($entry.Name)}};$rows.Add([ordered]@{index=$index;collisionName=$collisionName;sourceIndex=$sourceIndex;helpIndex=$helpIndex;messageIndex=$messageIndex;mode=$mode;contextFlag=$flag;attempt=$attempt;sourceCalls=$e.Calls;otherCalls=$e.Others;memberCount=$count;exception=$errorName;sourceUnits=(Units $fields['Source']);helpUnits=(Units $fields['HelpURL']);messageUnits=(Units $fields['Message']);stackUnits=(Units $fields['StackTraceString']);dataNull=($null -eq $fields['Data']);entryNames=($entryNames -join ';');errorMessageUnits=(Units $errorMessage);errorHResult=$errorHResult})};$index++}}}}}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();nullInputControls=$nullInputControls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 16 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS serialization boundaries: $($rows.Count) attempts"
